func (s *ClustersApiService) GetClusterMetrics(ctx context.Context, clusterId string, start time.Time, end time.Time,
	metricsTypes []api.MetricsType, numberOfSamples int32, groupBy string, nodePoolName string,
) (api.ImplResponse, error) {
	measurements := []api.GroupedMeasurementResponse{}
	responseCode := http.StatusOK
	capChecker := s.clusterCapabilityCheckerFactory(clusterId)
	groupByErr := validators.ValidateGroupByForMetrics(ctx, capChecker, metricsTypes, groupBy)
	if groupByErr != nil {
		return NewErrorResponse(&api.Error{Code: http.StatusBadRequest, Message: groupByErr.Error()}), nil
	}

	groupByEnum := client.MetricGroupBy(groupBy)
	for _, metricType := range metricsTypes {
		result := QueryClusterMetricType(ctx, s.orgUnitClient, clusterId, start, end, metricType, groupByEnum, numberOfSamples, nodePoolName)
		if result == nil {
			responseCode = http.StatusMultiStatus
			measurements = append(measurements, api.GroupedMeasurementResponse{
				Type: string(metricType),
			})
			continue
		}

		metricMeasurements, err := metrics.ParseMetricResultToGroupedMeasurement(ctx, string(metricType), groupBy, *result)
		if err != nil {
			return NewErrorResponse(&api.Error{Code: http.StatusServiceUnavailable, Message: "Error parsing metric response"}), err
		}
		measurements = append(measurements, metricMeasurements...)
	}

	responseStruct := api.GroupedMetricsResponse{Measurements: measurements}
	accept := runaictx.GetString(ctx, runaictx.CfAccept)
	if accept != nil && *accept == CsvAccept {
		data := GetMetricsCsv(&responseStruct, metricsTypes)
		response := runaihttp.CsvFile{Data: data, FileName: "cluster-metrics.csv"}
		return api.Response(responseCode, response), nil
	}
	return api.Response(responseCode, responseStruct), nil
}

