func (s *ClustersApiService) CreateCluster(ctx context.Context, ClusterCreationRequest api.ClusterCreationRequest) (api.ImplResponse, error) {
	tenantId, apiErr := s.extractTenantIdFromCtxAndRequestedId(ctx, int32(ClusterCreationRequest.TenantId))
	if apiErr != nil {
		return NewErrorResponse(apiErr), fmt.Errorf("%s", apiErr.Message)
	}

	ctx = context.WithValue(ctx, runaictx.CfTenantId, fmt.Sprintf("%d", tenantId))

	_, apiErr = ValidatePermittedTenantScope(ctx, tenantId)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	cluster := s.clusterApiToDao(ClusterCreationRequest)
	cluster.TenantId = tenantId

	_, apiErr = dao.CreateCluster(ctx, cluster)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	res := s.clusterDaoToApi(cluster, ext_api.VerbosityFull)

	logging.WithCtx(runaictx.LoggerHook(ctx)).Debugf("Created cluster <%s> in tenant <%d>", res.Uuid, res.TenantId)
	audit.AuditFromCtx(ctx).WithEntityName(cluster.Name).WithEntityType("cluster").WithEntityId(cluster.ID.String())
	s.nodepoolsApiService.ClusterNotification(ctx, api.ClusterNotification{
		Operation:              api.NOTIFICATIONOPERATION_CREATE,
		Id:                     cluster.ID.String(),
		Name:                   cluster.Name,
		SchedulingCapabilities: ClusterCreationRequest.DefaultNodepoolConfig.SchedulingCapabilities,
	})

	return api.Response(http.StatusCreated, res), nil
}

func (s *ClustersApiService) DeleteCluster(ctx context.Context, clusterId string, force bool) (api.ImplResponse, error) {
	tenantId, err := extractTenantIdFromCtxAndClusterId(ctx, clusterId)
	if err != nil {
		return NewErrorResponse(err), nil
	}
	ctx = context.WithValue(ctx, runaictx.CfTenantId, fmt.Sprintf("%d", tenantId))

	_, err = ValidatePermittedTenantScope(ctx, tenantId)
	if err != nil {
		return NewErrorResponse(err), nil
	}

	existingCluster, err := dao.GetClusterByIdAndTenantId(ctx, clusterId, tenantId, ext_api.VerbosityFull)
	if err != nil {
		return NewErrorResponse(err), nil
	}
	deleteResponse, err := s.deleteClusterInternal(ctx, force, existingCluster)
	if err != nil {
		return NewErrorResponse(err), nil
	}
	audit.AuditFromCtx(ctx).WithEntityType("cluster").WithEntityId(clusterId)
	return deleteResponse, nil
}

