func (s *ClustersApiService) GetClusterInstallInfoByUuid(ctx context.Context, clusterUuid string, version string, remoteClusterUrl string) (api.ImplResponse, error) {
	ingressClass, lastLiveness, err := s.getClusterInstallationInfo(ctx, clusterUuid)
	if err != nil {
		return NewErrorResponse(&api.Error{
			Code:    http.StatusInternalServerError,
			Message: fmt.Sprintf("Failed to get cluster installation info: %s", err.Error()),
		}), nil
	}

	installationConfig := runai_config.Get[*cluster_config.Installation]()
	helmRegistryUrl := installationConfig.HelmRegistryUrl
	fullHostKey := ctx.Value(utils.FullHostKey)
	if fullHostKey == nil {
		fullHostKey = s.appConfig.Host
	}
	clusterUrl := fullHostKey.(string)
	if remoteClusterUrl != "" {
		clusterUrl = remoteClusterUrl
	}
	tenantUrl := fullHostKey.(string)
	if runaictx.IsManagementTenant(ctx) {
		tenantUrl, err = s.GetTenantDomainForClusterId(ctx, clusterUuid)
		if err != nil {
			return NewErrorResponse(&api.Error{
				Code:    http.StatusInternalServerError,
				Message: err.Error(),
			}), nil
		}
	}

	bootstrapToken, err := s.mintInstallerBootstrapToken(ctx, clusterUuid)
	if err != nil {
		return NewErrorResponse(&api.Error{
			Code:    http.StatusInternalServerError,
			Message: fmt.Sprintf("Failed to mint installer bootstrap token: %s", err.Error()),
		}), nil
	}

	installationData := clusterinstallation.InstallationData{
		RepoURL:              helmRegistryUrl,
		HelmRegistryUsername: installationConfig.HelmRegistryUsername,
		PasswordPlaceholder:  installationConfig.HelmRegistryPasswordPlaceholder,
		IngressClass:         ingressClass,
		LastLiveness:         lastLiveness,
		FipsMode:             installationConfig.FipsMode,
		Host:                 tenantUrl,
		BootstrapToken:       bootstrapToken,
		Uuid:                 clusterUuid,
		RemoteClusterUrl:     clusterUrl,
		Version:              version,
	}

	installStr := s.clusterInstallService.GetInstallationString(&installationData)
	res := api.ClusterInstallationInfoResponse{
		InstallationStr: installStr,
		RepositoryName:  installationData.RepositoryName,
		ChartRepoURL:    installationData.RepoURL,
		BootstrapToken:  bootstrapToken,
	}
	logging.WithCtx(runaictx.LoggerHook(ctx)).Debugf("Returning cluster installation instruction "+
		"for cluster:<%s> ,chart repo name: <%s>, "+
		"chart repo url: <%s>", clusterUuid, installationData.RepositoryName, installationData.RepoURL)
	return api.Response(http.StatusOK, res), nil
}

func (s *ClustersApiService) UpdateClusterInfo(ctx context.Context, clusterId string, clusterInfo api.ClusterInfoSyncRequest) (api.ImplResponse, error) {
	tenantId, apiErr := extractTenantIdFromCtxAndClusterId(ctx, clusterId)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	clusterUuid, err1 := uuid.Parse(clusterId)
	if err1 != nil {
		return NewErrorResponse(api.NewError(http.StatusBadRequest, fmt.Sprintf("cluster Id must be a valid uuid. %s", clusterId), err1)), nil
	}

	// backward-compatability
	if clusterInfo.Dependencies != nil {
		if clusterInfo.Status == nil {
			clusterInfo.Status = &api.ClusterReportedStatus{}
		}
		clusterInfo.Status.Dependencies = api.ClusterDependenciesStatus{
			Required: clusterInfo.Dependencies.Required,
			Optional: clusterInfo.Dependencies.Optional,
		}
	}
	existingCluster, err := dao.GetClusterByIdAndTenantId(ctx, clusterId, tenantId, ext_api.VerbosityFull)
	if err != nil {
		return NewErrorResponse(err), nil
	}
	if (existingCluster.Domain != clusterInfo.Domain) || (existingCluster.Version != clusterInfo.Version) {
		err := s.updateInternalWorkloadClientForCluster(ctx, clusterId, clusterInfo.Domain)
		if err != nil {
			logging.WithCtx(runaictx.LoggerHook(ctx)).Infof("Failed to sync workload clients for cluster: %s", clusterId)
			apiErr = api.NewError(http.StatusInternalServerError,
				fmt.Sprintf("Failed to sync workload clients for cluster:  <%s>", clusterId), nil)
			return NewErrorResponse(apiErr), nil
		}
	}
	c := &models.Cluster{
		ID:       clusterUuid,
		TenantId: tenantId,
		Domain:   clusterInfo.Domain,
		Version:  clusterInfo.Version,
		Status:   utils.DerefOrZero(clusterInfo.Status),
	}

	apiErr = dao.UpdateClusterInfo(ctx, c)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	logging.WithCtx(runaictx.LoggerHook(ctx)).Debugf("Updated cluster-info for cluster <%s> in tenant <%d>", clusterId, tenantId)
	return NoContentResponse(), nil
}

