func (s *ClustersApiService) updateInternalWorkloadClientForCluster(ctx context.Context, clusterId string, domain string) error {
	filter := fmt.Sprintf("%s:%s %s:%s", "runai.client_type", "workloads_auth", "runai.cluster_id", clusterId)
	internalClients, err := s.idmClient.GetInternalClientByFilter(ctx, filter)
	if err != nil {
		return pkgErrors.Errorf("Error getting workload client for cluster: %s", clusterId)
	}
	if len(internalClients) == 0 {
		// If the workload_auth client is missing we assume this is an old versioned cluster,
		// so we don't need to update the workload client
		logging.WithCtx(runaictx.LoggerHook(ctx)).Infof("No workload client found for cluster %s, assuming old versioned cluster", clusterId)
		return nil
	} else if len(internalClients) > 1 {
		logging.WithCtx(runaictx.LoggerHook(ctx)).Warnf("Got more than a single workload client for cluster: %s should be exactly one, updating first client only", clusterId)
	}
	internalClient := internalClients[0]
	err = s.idmClient.AppendRedirectUriToInternalClient(ctx, internalClient, domain)
	if err != nil {
		return pkgErrors.Errorf("Error appending domain to workload client redirect uris, client id: %s", internalClient.ClientId)
	}
	return nil
}

func (s *ClustersApiService) deleteClusterInternal(ctx context.Context, force bool, existingCluster *models.Cluster) (api.ImplResponse, *api.Error) {
	var deleteResponse api.ImplResponse
	var err *api.Error
	if s.asyncDeleteConfig.Enabled {
		if force {
			err = s.clusterDeleter.ForceDeleteCluster(ctx, existingCluster)
		} else {
			err = s.clusterDeleter.AttemptToGracefullyDeleteCluster(ctx, existingCluster)
		}
		deleteResponse = AcceptedResponse()
	} else {
		// This part will be removed permanently when async delete is enabled by default
		err = s.clusterDeleter.NonAsyncDelete(ctx, existingCluster)
		deleteResponse = NoContentResponse()
	}
	return deleteResponse, err
}

func (s *ClustersApiService) extractTenantIdFromCtxAndRequestedId(ctx context.Context, requestedTenantId int32) (tenantId int32, apiErr *api.Error) {
	if runaictx.IsManagementTenant(ctx) && requestedTenantId != 0 {
		isValid, apiErr := isValidTenantId(ctx, s.tmClient, requestedTenantId)
		if isValid {
			return requestedTenantId, apiErr
		}
		return 0, apiErr
	}
	return ParseTenantId(ctx)
}

func (s *ClustersApiService) clusterDaoToApi(cluster *models.Cluster, verbosity ext_api.Verbosity) api.DisplayedCluster {
	c := api.DisplayedCluster{
		Uuid:      cluster.ID.String(),
		Name:      cluster.Name,
		TenantId:  cluster.TenantId,
		CreatedAt: cluster.CreatedAt,
		Version:   convutils.Ref(cluster.Version),
	}

	if verbosity == ext_api.VerbosityFull {
		c.Domain = convutils.Ref(cluster.Domain)
		c.Status = &api.ClusterDisplayedStatus{
			Conditions:   cluster.Status.Conditions,
			Operands:     cluster.Status.Operands,
			Dependencies: cluster.Status.Dependencies,
			Platform:     cluster.Status.Platform,
			Config:       cluster.Status.Config,
			State:        api.ClusterState(s.clusterStateCalculator.CalculateState(cluster)),
		}
		c.UpdatedAt = convutils.Ref(cluster.UpdatedAt)
		c.LastLiveness = cluster.LastLiveness
		c.DeleteRequestedAt = cluster.DeleteRequestedAt
		if cluster.DeletedAt.Valid {
			c.DeletedAt = convutils.Ref(cluster.DeletedAt.Time)
		}
	}

	return c
}

func (s *ClustersApiService) clusterApiToDao(c api.ClusterCreationRequest) *models.Cluster {
	cluster := &models.Cluster{
		Name:    c.Name,
		Domain:  c.Domain,
		Version: c.Version,
	}

	return cluster
}

func getClustersCountGroupBySubdomain(ctx context.Context, tenantId int32, permittedScopes authorization_api.PermittedScopes) ([]api.ClustersCount, *api.Error) {
	var clustersCount *models.ClustersCountSubdomainStatus
	clustersCount, apiErr := dao.GetClusterCountGroupBySubdomain(ctx, tenantId, permittedScopes)
	if apiErr != nil {
		return nil, apiErr
	}
	return []api.ClustersCount{
		{
			Key:   "true",
			Count: int32(clustersCount.EnabledCount),
		},
		{
			Key:   "false",
			Count: int32(clustersCount.DisabledCount),
		},
		{
			Key:   "unknown",
			Count: int32(clustersCount.MissingCount),
		},
	}, nil
}

func (s *ClustersApiService) GetClustersMinimalData(ctx context.Context, filterBy []string, offset int32, limit int32) (api.ImplResponse, error) {
	tenantId, apiErr := ParseTenantId(ctx)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	_, scopeErr := GetPermittedClusterScopes(ctx)
	if scopeErr != nil {
		return NewErrorResponse(scopeErr), nil
	}

	permittedScopes, _ := authorization_utils.GetPermittedScopesFromCtx(ctx)

	// Validate and parameterize filters
	filters, validationErr := models.ClusterMinimalQueryParser.Filters(filterBy)
	if validationErr != nil {
		return NewErrorResponse(api.NewError(http.StatusBadRequest, validationErr.Error(), validationErr)), nil
	}

	clusters, apiErr := dao.GetClusters(ctx, tenantId, ext_api.VerbosityFull, *permittedScopes, []string{}, false, false, offset, limit, filters)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	clustersMinimalData := make([]api.ClustersMinimalData, len(*clusters))
	for i, cluster := range *clusters {
		state := api.ClusterState(s.clusterStateCalculator.CalculateState(&cluster))
		responseInfo := cluster.ToMinimalData(state)

		clustersMinimalData[i] = responseInfo
	}

	return api.Response(http.StatusOK, api.GetClustersMinimalData200Response{
		Clusters: clustersMinimalData,
	}), nil
}

func (s *ClustersApiService) GetClusterMinimalDataById(ctx context.Context, clusterUuid string) (api.ImplResponse, error) {
	tenantId, apiErr := extractTenantIdFromCtxAndClusterId(ctx, clusterUuid)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	cluster, apiErr := dao.GetClusterByIdAndTenantId(ctx, clusterUuid, tenantId, ext_api.VerbosityFull)
	if apiErr != nil {
		return NewErrorResponse(apiErr), nil
	}

	state := api.ClusterState(s.clusterStateCalculator.CalculateState(cluster))
	clusterMinimalData := cluster.ToMinimalData(state)

	return api.Response(http.StatusOK, clusterMinimalData), nil
}
